(function(w){'use strict';if(!w.document)return;
const T=(r,e)=>document.documentElement.lang==='en'?e:r,E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),S=()=>w.VertexOwnedStays||[],N=x=>document.documentElement.lang==='en'?x.en:x.ru,P=x=>(x.photos||[])[0]||x.photo||'';
function open(id,c){let {shell,row,state,save,listing}=c,s=S().find(x=>x.id===state.id)||S()[0],back='<button class="vh-back" data-ha="menu">←</button>';
 if(id==='analytics')return shell(back+'<h2>'+T('Аналитика','Analytics')+'</h2><div class="vh-chips"><button class="on">'+T('Статистика','Statistics')+'</button><button>'+T('Тренды и советы','Trends & tips')+'</button></div><div class="vh-stats">'+[['4,67 ★',T('Общий рейтинг','Overall rating')],['3',T('Всего отзывов','Reviews')],['100%',T('Быстрота ответов','Response rate')],['2 970,48 $',T('Заработок за сентябрь','September earnings')],['609',T('Просмотры за 30 дней','Views in 30 days')],['16',T('30-дневные бронирования','30-day bookings')]].map(x=>'<article><strong>'+x[0]+'</strong><span>'+x[1]+'</span></article>').join('')+'</div><div class="vh-chart"><i style="height:15%"></i><i style="height:15%"></i><i style="height:92%"></i><i style="height:48%"></i><i style="height:31%"></i></div>','menu');
 if(id==='account'){let a=[['personal','○',T('Личная информация','Personal information')],['security','♢',T('Вход и безопасность','Login & security')],['privacy','◌',T('Конфиденциальность','Privacy')],['notifications','♧',T('Уведомления','Notifications')],['payments','▣',T('Платежи и выплаты','Payments & payouts')],['translation','◎',T('Перевод','Translation')],['permissions','⌘',T('Разрешения на бронирование','Booking permissions')],['business','▤',T('Деловые поездки','Business travel')],['accessibility','✧',T('Доступная среда','Accessibility')],['company','▦',T('Сведения о компании','Company information')],['tax','▥',T('Налоги','Taxes')]];return shell(back+'<h2>'+T('Настройки аккаунта','Account settings')+'</h2><div class="vh-menu">'+a.map(x=>row(x[0],x[1],x[2])).join('')+'</div>','menu')}
 if(id==='profile')return shell(back+'<div class="vh-profile"><i>F</i><h2>Firdavsiy</h2><strong>4,67 ★</strong><p>'+T('Хозяин · Tourism & Hospitality','Host · Tourism & Hospitality')+'</p></div><section class="vh-card"><p>▣ '+T('Моя работа: Tourism & Hospitality','My work: Tourism & Hospitality')+'</p><p>◎ '+T('Хочу побывать везде, где ещё не был ✈','I want to go everywhere I have not been ✈')+'</p><p>✧ '+T('Превращаю проживание в полноценное впечатление','I turn stays into experiences')+'</p><p>♢ '+T('Комфорт отеля с ощущением дома','Hotel comfort with the feeling of home')+'</p></section>','menu');
 if(id==='guest')return shell('<button class="vh-back" data-ha="today">←</button><h2>'+T('Прибытие через 8 дней','Arrival in 8 days')+'</h2><section class="vh-card"><div class="vh-guest"><i>O</i><div><strong>Omar Lehat</strong><p>+1 '+T('взрослый','adult')+'</p></div></div></section><section class="vh-card"><strong>'+T('Правила отмены','Cancellation policy')+'</strong><p>'+T('Умеренные','Moderate')+'</p></section><section class="vh-card"><div class="vh-price"><strong>497,49 $</strong><small>'+T('Итого за 6 ночей','Total for 6 nights')+'</small></div></section>'+row('manage','✎',T('Управление бронированием','Manage reservation'))+row('message-guest','□',T('Сообщение гостю','Message guest')),'today');
 if(id==='amenities'){let g=[[T('Спальня и прачечная','Bedroom & laundry'),['Стиральная машина','Сушильная машина']],[T('Развлечения','Entertainment'),['Телевизор','Тренажеры']],[T('Отопление и охлаждение','Heating & cooling'),['Кондиционер','Камин электрический']],[T('Безопасность жилья','Home safety'),['Датчик дыма','Аптечка']]];return shell('<button class="vh-back" data-ha="selected">←</button><h2>'+T('Какие удобства вас ждут','Amenities')+'</h2>'+g.map(x=>'<section class="vh-amenity"><h3>'+x[0]+'</h3>'+x[1].map(y=>'<p>◉ '+y+'</p>').join('')+'</section>').join(''),'listings')}
 if(id==='rules'){let q=(k,l)=>'<div class="vh-toggle"><strong>'+l+'</strong><button data-hx="'+k+'" class="'+(state[k]?'on':'')+'"><span>✓</span></button></div>';shell('<button class="vh-back" data-ha="selected">←</button><h2>'+T('Правила дома','House rules')+'</h2><p class="vh-muted">'+T('Ваши правила обязательны для гостей.','Your rules apply to guests.')+'</p>'+q('pets',T('Можно с питомцами','Pets allowed'))+q('events',T('Мероприятия разрешены','Events allowed'))+q('smoking',T('Курение и вейпинг разрешены','Smoking & vaping allowed'))+q('photo',T('Коммерческая фото- и видеосъемка разрешена','Commercial photo/video allowed'))+'<div class="vh-time"><strong>'+T('Часы тишины','Quiet hours')+'</strong><div><input value="23:00"><input value="07:00"></div></div><button class="vh-primary" data-ha="save">'+T('Сохранить','Save')+'</button>','listings');document.querySelectorAll('[data-hx]').forEach(b=>b.onclick=()=>{let k=b.dataset.hx;state[k]=!state[k];save();b.classList.toggle('on',state[k])});return}
 if(id==='photos')return shell('<button class="vh-back" data-ha="selected">←</button><h2>'+T('Фототур','Photo tour')+'</h2><p class="vh-muted">'+T('Подбирайте фото и добавляйте детали для каждой комнаты.','Choose photos and add room details.')+'</p><div class="vh-photos">'+((s?.photos||[s?.photo]).filter(Boolean).map((x,i)=>'<figure><img src="'+E(x)+'"><figcaption>'+(i?T('Комната','Room'):T('Главное фото','Cover photo'))+'</figcaption></figure>').join(''))+'</div><button class="vh-primary" data-ha="add-photo">'+T('Добавить фото','Add photo')+'</button>','listings');
 if(id==='edit')return shell('<button class="vh-back" data-ha="selected">←</button><h2>'+T('Редактор объявления','Listing editor')+'</h2><div class="vh-editor"><section><strong>'+T('Фототур','Photo tour')+'</strong><img src="'+E(P(s))+'"></section>'+row('title','T',T('Название','Title'))+row('type','⌂',T('Тип жилья','Property type'))+row('beds','▤',T('Спальные места','Sleeping arrangements'))+row('amenities','◇',T('Удобства','Amenities'))+row('rules','⌂',T('Правила дома','House rules'))+'</div>','listings');
 if(id==='thread')return shell('<button class="vh-back" data-ha="messages">←</button><h2>Tarkan</h2><div class="vh-thread"><p class="guest">'+T('Добрый день! Подскажите пожалуйста время заселения.','Hello! Please confirm check-in time.')+'</p><p class="host">'+T('Здравствуйте! Код доступа отправим в день заселения до 14:00.','Hello! We will send the access code before 14:00 on arrival day.')+'</p></div><form class="vh-compose"><input placeholder="'+T('Сообщение…','Message…')+'"><button>➤</button></form>','messages');
 if(id==='message-settings')return shell('<button class="vh-back" data-ha="messages">←</button><h2>'+T('Настройки переписки','Message settings')+'</h2>'+row('quick-replies','□',T('Редактор готовых ответов','Quick reply editor'))+row('recommended','✧',T('Рекомендуемые ответы','Suggested replies'))+row('archive','▣',T('В архиве','Archived'))+row('feedback','➤',T('Дать обратную связь','Send feedback')),'messages');
 if(id==='payments')return shell('<button class="vh-back" data-ha="account">←</button><h2>'+T('Платежи и выплаты','Payments & payouts')+'</h2><h3>'+T('Путешествия','Travel')+'</h3>'+row('pay-methods','▣',T('Способы оплаты','Payment methods'))+row('pay-history','☷',T('Ваши платежи','Your payments'))+'<h3>'+T('Прием гостей','Hosting')+'</h3>'+row('payouts','▣',T('Способы выплаты','Payout methods'))+row('transactions','▥',T('История операций','Transaction history'))+'<p class="notice">'+T('Реальные платежи и выплаты пока не подключены.','Real payments and payouts are not connected yet.')+'</p>','menu');
 if(['personal','security','privacy','notifications','payments','translation','permissions','business','accessibility','company','tax','resources'].includes(id)&&w.VertexProfileMenu?.open)return w.VertexProfileMenu.open(id==='translation'?'translate':id==='accessibility'?'access':id==='resources'?'guide':id);
 if(id==='message-guest')return open('thread',c);
 if(id==='manage')return open('guest',c);
 if(id==='quick-replies'||id==='recommended'||id==='archive'||id==='feedback')return open('message-settings',c);
 if(id==='title'||id==='type'||id==='beds')return open('edit',c);
 if(id==='add-photo')return open('photos',c);
 if(id==='new'&&w.VertexRentals?.createListing)return w.VertexRentals.createListing();
 if(id==='team'&&w.VertexGroup?.requests)return w.VertexGroup.requests();
 if(id==='help'&&w.VertexGuestGuide?.open)return w.VertexGuestGuide.open();
 if(id==='calendar')return w.VertexHostConsole.open('calendar');
 if(id==='messages')return w.VertexHostConsole.open('messages');
 if(id==='listings')return w.VertexHostConsole.open('listings');
 if(id==='save')return listing(state.id);
 return shell('<button class="vh-back" data-ha="account">←</button><h2>'+T('Vertex / Views','Vertex / Views')+'</h2><p class="notice">'+T('Раздел работает в демонстрационном режиме и сохраняет настройки локально.','This section works in demo mode and saves settings locally.')+'</p><button class="vh-primary" data-ha="account">'+T('Готово','Done')+'</button>','menu');
}
w.VertexHostMore={open};})(window);